{
  "pick": 0,
  "name_zh": "寒霜終焉",
  "concept": "將累積的連擊節奏轉化為毀滅性的寒冰衝擊。",
  "cast_flavor": "隨著連擊節奏的加速，寒冰在法器中凝結成致命的尖刺。"
}

{
  "pick": 1,
  "name_zh": "暴怒重擊",
  "concept": "將積蓄的怒火轉化為沉重的打擊力，強行壓制對手。",
  "cast_flavor": "隨著怒火噴湧，沉重的打擊重重落在對手身上。"
}

{
  "pick": 1,
  "name_zh": "真理之眼",
  "concept": "透過感知波動揭示隱匿者的真面目與周遭陷阱。",
  "cast_flavor": "光輝灑落，將所有偽裝的陰影與暗藏的危機徹底顯現。"
}

{
  "pick": 1,
  "name_zh": "顯現之光",
  "concept": "揭示範圍內敵人的真身與周遭的陷阱。",
  "cast_flavor": "光輝灑落，讓隱藏的行蹤與危機無所遁形。"
}

{
  "pick": 0,
  "name_zh": "碎霜射擊",
  "concept": "藉由射擊將極寒的頻率灌入目標體內。",
  "cast_flavor": "當箭矢沒入目標，凍結的餘頻將瞬間爆發。"
}

{
  "pick": 1,
  "name_zh": "刃紋刻印",
  "concept": "在周身劃出隱形的切割軌跡，留下無法抹滅的痕跡。",
  "cast_flavor": "揮舞武器劃過空氣，讓殘留的紋路成為致命的預兆。"
}

{
  "pick": 0,
  "name_zh": "暗影落印",
  "concept": "利用標記引發的連鎖反應，將黑暗力量灌注於目標身上。",
  "cast_flavor": "隨著印記顫動，無形的陰影將目標重重擊落。"
}

{
  "pick": 0,
  "name_zh": "迴旋斬擊",
  "concept": "藉由武器帶動周遭氣流，對周圍敵人造成傷害並拖慢其行動。",
  "cast_flavor": "揮動武器劃開空氣，阻礙著敵人的步履。"
}

{
  "pick": 0,
  "name_zh": "俯瞰重擊",
  "concept": "利用高度優勢對目標發動更為精準且沉重的打擊。",
  "cast_flavor": "從高處俯衝而下，將所有重量傾注於這一擊之中。"
}

{
  "pick": 0,
  "name_zh": "狂暴氣旋",
  "concept": "藉由燃燒憤怒驅動的強大氣流。",
  "cast_flavor": "隨着憤怒的釋放，狂暴的風壓將撕裂一切阻礙。"
}

{
  "pick": 0,
  "name_zh": "狂飆氣流",
  "concept": "藉由憤怒驅動的強大氣流。",
  "cast_flavor": "隨着憤怒的釋放，狂暴的風壓將撕裂一切阻礙。"
}

{
  "pick": 4,
  "name_zh": "冰紋刻印",
  "concept": "在敵人的防禦隙間刻下冰冷的印記。",
  "cast_flavor": "揮動武器劃過寒氣，於傷口處留下不散的冰紋。"
}

{
  "pick": 0,
  "name_zh": "碎骨追擊",
  "concept": "利用既有的衝撞力道，在擊中目標時瞬間爆發更強的打擊力。",
  "cast_flavor": "趁著目標被撞飛的餘波，將手中的武器狠狠砸入其骨縫之中。"
}

{
  "pick": 1,
  "name_zh": "鷹眼",
  "concept": "立於高處俯瞰戰局時，能凝聚精神並獲得屏障保護。",
  "cast_flavor": "目光穿透迷霧，意志化作堅實的護盾。"
}

{
  "pick": 2,
  "name_zh": "雷咒",
  "concept": "將暗影與雷電交織的咒文施放於目標身上。",
  "cast_flavor": "陰影在雷鳴中扭曲，將狂暴的電光注入目標體內。"
}

{
  "pick": 0,
  "name_zh": "追蹤印記",
  "concept": "在移動後精準鎖定目標並留下無法擺脫的印記。",
  "cast_flavor": "箭矢劃破空氣，在目標身上烙下無法抹去的追蹤符文。"
}

{
  "pick": 4,
  "name_zh": "掠奪者烙印",
  "concept": "藉由烙印標記強行奪取對方的加持，為自己換取生存契機。",
  "cast_flavor": "武器劃過空氣的殘影在目標身上刻下印記，將對方的榮耀強行剝離並轉移。"
}

{
  "pick": 3,
  "name_zh": "陰影烙印",
  "concept": "利用暗影頻率在敵人身上留下無法擺脫的印記。",
  "cast_flavor": "在虛無的裂隙中，將不祥的陰影強行烙印於目標身上。"
}

{
  "pick": 0,
  "name_zh": "精準標記",
  "concept": "透過極度專注的引導，在目標身上留下無法擺脫的印記。",
  "cast_flavor": "當精神完全凝聚於一點，目標的命運便已在印記中寫下。"
}

{
  "pick": 0,
  "name_zh": "暗影重奏",
  "concept": "藉由連擊堆疊的餘頻，引發黑暗能量的爆裂。",
  "cast_flavor": "將累積的殺意轉化為漆黑的衝擊，讓敵人陷入恐懼。"
}

{
  "pick": 0,
  "name_zh": "暗影重奏",
  "concept": "藉由連擊堆疊的餘頻，引發黑暗能量的爆裂。",
  "cast_flavor": "將累積的殺意轉化為漆黑的衝擊，讓敵人陷入沉默。"
}

{
  "pick": 1,
  "name_zh": "吐納",
  "concept": "透過調整呼吸節奏來修復傷口並凝聚生命力。",
  "cast_flavor": "平穩的呼吸在胸腔迴盪，將虛弱的生機重新聚攏。"
}

{
  "pick": 0,
  "name_zh": "鋒芒烙印",
  "concept": "在敵方戰場劃出無法抹去的刻痕，引發對方的敵意。",
  "cast_flavor": "武器劃過地面，留下的痕跡令敵人無法忽視你的存在。"
}

{
  "pick": 2,
  "name_zh": "烈焰重擊",
  "concept": "將武器的揮砍與燃燒的頻率融合，產生強大的衝擊力。",
  "cast_flavor": "武器劃過空氣的瞬間，將熾熱的餘燼悉數釋放於敵陣。"
}

{
  "pick": 0,
  "name_zh": "裂解頻率",
  "concept": "藉由承受傷害時釋放的能量，使敵人的防禦變得脆弱。",
  "cast_flavor": "在震盪的餘頻中，目標的結構開始崩解。"
}

{
  "pick": 2,
  "name_zh": "寒冰之怒",
  "concept": "在承受傷害時將寒意轉化為憤怒的能量。",
  "cast_flavor": "冰冷的寒氣隨著痛楚交織，在周身激盪出狂暴的餘韻。"
}

{
  "pick": 1,
  "name_zh": "腐蝕刃紋",
  "concept": "在敵方周遭刻下帶有毒素的刻印，持續影響目標與環境。",
  "cast_flavor": "揮動遠程武器劃過空氣，在敵人身側留下無法磨滅的腐蝕痕跡。"
}
